from jsonb_to_recordset($payload$[{"id":"TR-060","quick":"Эффект обычно не мгновенный: на странице клиники результат предлагают оценивать в динамике в течение 2–6 недель.","urgency":"Обычная","kind":"FAQ","title":"Когда начинает действовать гиалуроновая кислота","patient_answer":"Эффект обычно не мгновенный: на странице клиники результат предлагают оценивать в динамике в течение 2–6 недель.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"гиалуронка эффект когда подействует 2 6 недель","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-061","quick":"У ответивших на лечение пациентов симптоматический эффект может сохраняться несколько месяцев, но срок индивидуален и заранее не гарантируется.","urgency":"Обычная","kind":"FAQ","title":"Сколько держится эффект гиалуроновой кислоты","patient_answer":"У ответивших на лечение пациентов симптоматический эффект может сохраняться несколько месяцев, но срок индивидуален и заранее не гарантируется.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"сколько держится гиалуронка срок эффект","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-062","quick":"При тяжёлом артрозе и выраженной деформации вероятность заметного длительного ответа ниже; инъекция может обсуждаться как симптоматическая мера, но не восстанавливает утраченный хрящ.","urgency":"Обычная","kind":"FAQ","title":"Гиалуроновая кислота при «кости о кость»","patient_answer":"При тяжёлом артрозе и выраженной деформации вероятность заметного длительного ответа ниже; инъекция может обсуждаться как симптоматическая мера, но не восстанавливает утраченный хрящ.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"кость о кость 4 стадия тяжелый артроз нет хряща","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-063","quick":"При наличии показаний лечение обоих суставов возможно, но решение принимает врач; для каждого сустава нужен отдельный стерильный шприц.","urgency":"Обычная","kind":"FAQ","title":"Можно ли сделать гиалуронку сразу в два колена","patient_answer":"При наличии показаний лечение обоих суставов возможно, но решение принимает врач; для каждого сустава нужен отдельный стерильный шприц.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"два колена оба колена два сустава","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-064","quick":"Спокойная бытовая активность обычно допустима, но интенсивную нагрузку в первые 24–48 часов ограничивают по рекомендации врача.","urgency":"Обычная","kind":"После процедуры","title":"Можно ли ходить после укола в сустав","patient_answer":"Спокойная бытовая активность обычно допустима, но интенсивную нагрузку в первые 24–48 часов ограничивают по рекомендации врача.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"ходить нагрузка после укола после гиалуронки","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-065","quick":"Возможность вождения зависит от обработанного сустава, стороны введения и самочувствия; заранее гарантировать её нельзя.","urgency":"Обычная","kind":"После процедуры","title":"Можно ли за руль после внутрисуставной инъекции","patient_answer":"Возможность вождения зависит от обработанного сустава, стороны введения и самочувствия; заранее гарантировать её нельзя.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"за руль машина водить после укола","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-066","quick":"Обычно ощущается кратковременный укол и давление; выраженность дискомфорта зависит от сустава, воспаления и индивидуальной чувствительности.","urgency":"Обычная","kind":"FAQ","title":"Больно ли делать внутрисуставную инъекцию","patient_answer":"Обычно ощущается кратковременный укол и давление; выраженность дискомфорта зависит от сустава, воспаления и индивидуальной чувствительности.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"больно укол в колено обезболивание","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставные инъекции"}},{"id":"TR-067","quick":"Повторное введение рассматривают при значимом предыдущем эффекте, возвращении симптомов и отсутствии противопоказаний; автоматического графика для всех нет.","urgency":"Обычная","kind":"FAQ","title":"Можно ли повторять курс гиалуроновой кислоты","patient_answer":"Повторное введение рассматривают при значимом предыдущем эффекте, возвращении симптомов и отсутствии противопоказаний; автоматического графика для всех нет.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"повторить курс как часто гиалуронка","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-068","quick":"Быстро нарастающая боль, резкий отёк, выраженное покраснение, жар кожи, температура или ухудшение самочувствия требуют незамедлительной медицинской оценки.","urgency":"Красная","kind":"Красный флаг","title":"Сильная боль и отёк после внутрисуставной инъекции","patient_answer":"Быстро нарастающая боль, резкий отёк, выраженное покраснение, жар кожи, температура или ухудшение самочувствия требуют незамедлительной медицинской оценки.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"сильно болит отек красный сустав температура после укола","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-069","quick":"Нет: реалистичная цель — уменьшить боль и скованность и поддержать движение; процедура не наращивает новый хрящ и не устраняет причину артроза.","urgency":"Обычная","kind":"FAQ","title":"Восстанавливает ли гиалуроновая кислота хрящ","patient_answer":"Нет: реалистичная цель — уменьшить боль и скованность и поддержать движение; процедура не наращивает новый хрящ и не устраняет причину артроза.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"восстановить нарастить хрящ лечит артроз","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-070","quick":"Инъекция не исправляет слабость мышц, походку и перегрузку; уменьшение симптомов можно использовать для восстановления силы, движения и контроля сустава.","urgency":"Обычная","kind":"Маршрутизация","title":"Зачем после инъекции ЛФК и реабилитация","patient_answer":"Инъекция не исправляет слабость мышц, походку и перегрузку; уменьшение симптомов можно использовать для восстановления силы, движения и контроля сустава.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"лфк реабилитация после укола упражнения","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-071","quick":"МРТ требуется не перед каждой инъекцией: врач выбирает объём обследования по клинической ситуации и может использовать осмотр, рентген, УЗИ или МРТ.","urgency":"Обычная","kind":"FAQ","title":"Нужно ли МРТ перед уколом в сустав","patient_answer":"МРТ требуется не перед каждой инъекцией: врач выбирает объём обследования по клинической ситуации и может использовать осмотр, рентген, УЗИ или МРТ.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"мрт перед уколом обследование перед инъекцией","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставные инъекции"}},{"id":"TR-072","quick":"Полезно взять заключения врачей, рентген/МРТ, результаты УЗИ сустава, список принимаемых лекарств и сведения об аллергиях.","urgency":"Обычная","kind":"Подготовка","title":"Что взять с собой перед внутрисуставной инъекцией","patient_answer":"Полезно взять заключения врачей, рентген/МРТ, результаты УЗИ сустава, список принимаемых лекарств и сведения об аллергиях.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"что взять подготовка снимки лекарства аллергии","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставные инъекции"}},{"id":"TR-073","quick":"УЗ-навигация позволяет видеть иглу, суставную полость, выпот и окружающие структуры в реальном времени и особенно полезна при сложной анатомии.","urgency":"Обычная","kind":"FAQ","title":"Зачем УЗ-контроль при уколе в сустав","patient_answer":"УЗ-навигация позволяет видеть иглу, суставную полость, выпот и окружающие структуры в реальном времени и особенно полезна при сложной анатомии.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"3 500 ₽ + медицинское изделие","code":"","keywords":"зачем узи укол под узи навигация","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-074","quick":"Не всегда: для коленного сустава необходимость навигации оценивается индивидуально; она особенно полезна при выпоте, деформации и сложной анатомии.","urgency":"Обычная","kind":"FAQ","title":"Обязательно ли колоть колено под УЗИ","patient_answer":"Не всегда: для коленного сустава необходимость навигации оценивается индивидуально; она особенно полезна при выпоте, деформации и сложной анатомии.","module":"Травматология","data":{"ask":["Какой сустав или зона?","Есть ли диагноз/назначение и актуальные исследования?"],"dont":["Не подбирать препарат или курс за врача.","Не обещать гарантированный результат."],"next":"При отсутствии полноценного актуального назначения — консультация травматолога-ортопеда.","price":"","code":"","keywords":"колено под узи обязательно инъекция без узи","prep":"","doctor":"Какалов Ислам Алиевич","source":"Страница Green Clinic: внутрисуставное введение гиалуроновой кислоты"}},{"id":"TR-075","quick